CREATE TABLE business_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, order_date date NOT NULL DEFAULT current_date, platform text NOT NULL, order_id text NOT NULL, sku_id uuid NOT NULL REFERENCES skus(id), qty_ordered numeric(12,2) NOT NULL DEFAULT 1, qty_delivered numeric(12,2) NOT NULL DEFAULT 0, qty_returned numeric(12,2) NOT NULL DEFAULT 0, sale_price numeric(12,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Pending', delivery_date date, return_date date, customer_location text, refund_amount numeric(12,2) NOT NULL DEFAULT 0, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by, order_id, platform))